        c = _c;
    }

    function run(address newConfig) public {
        address before = address(c.lrtConfig());
        if (newConfig == address(0)) {
            require(before == address(0), "precondition: zero-address outcome already set");
        }

        bool reverted;
        try c.updateLRTConfig(newConfig) {
            reverted = false;
        } catch {
            reverted = true;
