contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset) public payable {
        uint256 limit;
        bool reverted;
        try c.getAssetCurrentLimit(asset) returns (uint256 v) {
            limit = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 depositLimit;
        bool configOk;
        if (!reverted) {
            (bool success, bytes memory data) = address(c).staticcall(
                abi.encodeWithSignature("lrtConfig()")
            );
            configOk = success && data.length >= 32;
        }

        assert(
            reverted ||
                !configOk ||
                limit <= ILRTConfig(callLrtConfig()).depositLimitByAsset(asset)
        );
    }

    function callLrtConfig() private view returns (address) {
        (bool success, bytes memory data) = address(c).staticcall(
            abi.encodeWithSignature("lrtConfig()")
        );
        require(success && data.length >= 32, "no config");
        address cfg;
        assembly {
            cfg := mload(add(data, 32))
        }
        return cfg;
    }

    receive() external payable {}
}

