contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address delegator) public payable {
        require(delegator != address(0));

        address[] memory queue = c.getNodeDelegatorQueue();

        c.updateMaxNodeDelegatorCount(queue.length + 1);
        address[] memory newQueue = new address[](1);
        newQueue[0] = delegator;

        try c.addNodeDelegatorContractToQueue(newQueue) {
            address[] memory afterQueue = c.getNodeDelegatorQueue();
            assert(afterQueue.length == queue.length + 1);
            assert(afterQueue[queue.length] == delegator);
            for (uint256 i = 0; i < afterQueue.length; i++) {
                assert(afterQueue[i] != address(0));
            }
        } catch {
            address[] memory afterQueue = c.getNodeDelegatorQueue();
            assert(afterQueue.length == queue.length);
        }
    }

    receive() external payable {}
}

