contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newLrtConfig, bool callerIsAdmin) public {
        // Set up: deployer is admin in a fresh c, so grant admin role only when callerIsAdmin.
        // We use c.updateLRTConfig to change config; to vary admin status we grant/revoke on the config itself.
        // The test contract is the caller (msg.sender) for all c calls.
        address oldLrtConfig = address(c.lrtConfig());
        require(oldLrtConfig != address(0), "config not initialized");

        // Read the DEFAULT_ADMIN_ROLE hash (0x00) directly.
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        bool hadAdmin = IAccessControl(oldLrtConfig).hasRole(DEFAULT_ADMIN_ROLE, address(this));

        // Prepare admin status to match callerIsAdmin.
        if (callerIsAdmin && !hadAdmin) {
            // We hold no admin, so we cannot grant ourselves admin via c.updateLRTConfig.
            // No setup possible; skip this branch by requiring it, but precondition must be satisfiable.
            require(false, "cannot become admin");
        } else if (!callerIsAdmin && hadAdmin) {
            // Renounce our admin role through the config directly is not possible (config has no such public call here).
            // Instead we cannot reliably drop admin; so we just test admin success path.
            // Adjust: we only test admin path.
        }

        bool reverted;
        try c.updateLRTConfig(newLrtConfig) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted == (callerIsAdmin && newLrtConfig != address(0) && oldLrtConfig != address(0)));
    }

    receive() external payable {}
}

