contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newConfig) public {
        require(newConfig != address(c), "need a different config to observe a change");

        address before = address(c.lrtConfig());
        bool reverted;
        try c.updateLRTConfig(newConfig) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (newConfig == address(0)) {
            // Zero address must always be rejected, regardless of caller privileges.
            assert(reverted);
        } else {
            // For a nonzero address the outcome depends only on admin status:
            // success iff the caller is admin, in which case the stored config flips.
            address after_ = address(c.lrtConfig());
            if (!reverted) {
                assert(after_ == newConfig && after_ != before);
            } else {
                assert(after_ == before);
            }
        }
    }
}

