contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata nodeDelegators, uint256 maxCount) public {
        // Set up: caller is not LRT admin, and lrtConfig is not set on c yet, so hasRole calls will revert.
        uint256 beforeLen = c.getNodeDelegatorQueue().length;
        uint256 beforeMax = c.maxNodeDelegatorCount();

        // Attempt to change max count as admin - this should revert because caller is not admin (lrtConfig unset).
        bool maxReverted;
        try c.updateMaxNodeDelegatorCount(maxCount) {
            maxReverted = false;
        } catch {
            maxReverted = true;
        }

        // The decisive call: addNodeDelegatorContractToQueue should revert as caller is not admin.
        bool addReverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // General rule: If max count change reverted (caller not admin), then adding node delegators must also revert
        // and queue length must stay unchanged. Additionally, if maxCount is less than beforeMax+input length, and
        // caller were admin, it would revert, but here caller isn't admin so it always reverts when maxReverted.
        assert(
            (maxReverted && addReverted && c.getNodeDelegatorQueue().length == beforeLen && c.maxNodeDelegatorCount() == beforeMax)
            ||
            (!maxReverted && !addReverted && c.getNodeDelegatorQueue().length == beforeLen + nodeDelegators.length && c.maxNodeDelegatorCount() == maxCount)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata nodeDelegators) public {
        require(nodeDelegators.length > 0 && nodeDelegators.length <= 10, "bad input length");

        uint256 beforeLen = c.getNodeDelegatorQueue().length;
        uint256 beforeMax = c.maxNodeDelegatorCount();

        bool addReverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        assert(
            addReverted &&
            c.getNodeDelegatorQueue().length == beforeLen &&
            c.maxNodeDelegatorCount() == beforeMax
        );
    }
}
